    segs=[(i,[j for j,v in enumerate(r) if v not in (0,2)]) for i,r in enumerate(g) if any(v not in (0,2) for v in r)]
    (a,j1),(b,j2)=segs; b=bars[0]
    c=j1[0]+1  # color of first segment +1
    lo,hi=max(min(j1),min(j2)),min(max(j1),max(j2))
